binary-search.code:
def solve(nums, target):
    left, right = 0, len(nums) - 1
    while left <= right:
        middle = (left + right) // 2
        if nums[middle] == target:
            return middle
        if nums[middle] < target:
            left = middle + 1
        else:
            right = middle - 1
    return -1

palindrome.code:
def solve(text):
    left, right = 0, len(text) - 1
    while left < right:
        if text[left] != text[right]:
            return False
        left += 1
        right -= 1
    return True

balanced-brackets.code:
def solve(text):
    stack = []
    opening = {')': '(', ']': '[', '}': '{'}
    for char in text:
        if char in '([{':
            stack.append(char)
        elif not stack or stack.pop() != opening[char]:
            return False
    return not stack

factorial.code:
def solve(n):
    if n <= 1:
        return 1
    return n * solve(n - 1)

max-subarray.code:
def solve(nums):
    ending = best = nums[0]
    for value in nums[1:]:
        ending = max(value, ending + value)
        best = max(best, ending)
    return best

unique-window.code:
def solve(text):
    last = {}
    left = best = 0
    for right, char in enumerate(text):
        if char in last:
            left = max(left, last[char] + 1)
        last[char] = right
        best = max(best, right - left + 1)
    return best

stair-ways.code:
def solve(n):
    previous, current = 1, 1
    for step in range(2, n + 1):
        previous, current = current, previous + current
    return current

lc-two-sum.code:
def solve(nums, target):
    seen = {}
    for i, n in enumerate(nums):
        if target-n in seen:
            return [seen[target-n], i]
        seen[n] = i

lc-valid-parentheses.code:
def solve(s):
    stack=[]
    pairs={")":"(", "]":"[", "}":"{"}
    for c in s:
        if c in pairs:
            if not stack or stack.pop()!=pairs[c]: return False
        else: stack.append(c)
    return not stack

